values.value:
{
  "channel": "{{CHANNEL_ID}}",
  "text": "Critical Case {{CASE_NUMBER}}: {{SUBJECT}}",
  "blocks": [
    {
      "type": "header",
      "text": {
        "type": "plain_text",
        "text": "🚨 Critical Incident: {{CASE_NUMBER}}",
        "emoji": true
      }
    },
    {
      "type": "section",
      "fields": [
        { "type": "mrkdwn", "text": "*Account:*\n{{ACCOUNT_NAME}}" },
        { "type": "mrkdwn", "text": "*Priority:*\n{{PRIORITY}}" },
        { "type": "mrkdwn", "text": "*Status:*\n{{STATUS}}" },
        { "type": "mrkdwn", "text": "*Salesforce:*\n<{{CASE_URL}}|Open Record>" }
      ]
    },
    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": "*Issue Summary:*\n{{SUBJECT}}"
      }
    },
    { "type": "divider" },
    {
      "type": "actions",
      "block_id": "case_actions_{{CASE_ID}}",
      "elements": [
        {
          "type": "button",
          "text": { "type": "plain_text", "text": "✅ Claim Case" },
          "style": "primary",
          "action_id": "claim_case",
          "value": "{{CASE_ID}}"
        },
        {
          "type": "button",
          "text": { "type": "plain_text", "text": "🔥 Escalate" },
          "style": "danger",
          "action_id": "escalate_case",
          "value": "{{CASE_ID}}"
        }
      ]
    }
  ]
}
